                            `<tr><td>${item?.SNo ?? ''}</td><td>${item?.description ?? ''}</td><td>${item?.quantity ?? ''}</td><td>${item?.rate ?? ''}</td><td>${item?.cost ?? ''}</td></tr>`
                        ).join('') +
                        '</tbody></table>'
                    : '<p>No electrical work registered</p>'}
                </div>
            ` : ''}

                ${engineeringWorks.value && typeof engineeringWorks.value.length === 'number' && engineeringWorks.value.length > 0 ? `
                <div class="section">
                    <h2>Engineering Works</h2>
                    <table>
                        <thead>
                            <tr><th>S.No</th><th>Description</th><th>Quantity</th><th>Rate</th><th>Total</th></tr>
                        </thead>
                        <tbody>
                            ${engineeringWorks.value.map(item => 
                                `<tr><td>${item?.SNo ?? ''}</td><td>${item?.description ?? ''}</td><td>${item?.quantity ?? ''}</td><td>${item?.rate ?? ''}</td><td>${item?.cost ?? ''}</td></tr>`
                            ).join('')}
                        </tbody>
                    </table>
                </div>
            ` : ''}

                ${additionalWorks.value && typeof additionalWorks.value.length === 'number' && additionalWorks.value.length > 0 ? `
                <div class="section">
                    <h2>Additional Works</h2>
                    <table>
                        <thead>
                            <tr><th>S.No</th><th>Description</th><th>Quantity</th><th>Rate</th><th>Total</th></tr>
                        </thead>
                        <tbody>
                            ${additionalWorks.value.map(item => 
                                `<tr><td>${item?.SNo ?? ''}</td><td>${item?.description ?? ''}</td><td>${item?.quantity ?? ''}</td><td>${item?.rate ?? ''}</td><td>${item?.cost ?? ''}</td></tr>`
                            ).join('')}
                        </tbody>
                    </table>
                </div>
            ` : ''}
            
            <div class="section">
                <h2>Total Cost Note</h2>
                <table class="data-table">
                    <tr>
                        <th>Total Spares Cost</th>
                        <td>${costNote.value?.spares?.toLocaleString() || '0'}/=</td>
                    </tr>
                       <tr>
                        <th>Total Tyres Cost</th>
                        <td>${costNote.value?.tyres?.toLocaleString() || '0'}/=</td>
                    </tr>
                    <tr>
                        <th>Total Body Works Cost</th>
                        <td>${costNote.value?.body_works?.toLocaleString() || '0'}/=</td>
                    </tr>
                    <tr>
                        <th>Total Electrical Works Cost</th>
                        <td>${costNote.value?.electrical_works?.toLocaleString() || '0'}/=</td>
                    </tr>
                    <tr>
                        <th>Total Labour Cost</th>
                        <td>${costNote.value?.labour?.toLocaleString() || '0'}/=</td>
                    </tr>
                     <tr>
                        <th>Total Engineering Works Cost</th>
                        <td>${costNote.value?.engineering?.toLocaleString() || '0'}/=</td>
                    </tr>
                     <tr>
                        <th>Total Additional Works Cost</th>
                        <td>${costNote.value?.additional?.toLocaleString() || '0'}/=</td>
                    </tr>
                    <tr>
                        <th><b>Total Cost</b></th>
                        <th><b>${costNote.value?.total?.toLocaleString() || '0'}/=</b></th>
                    </tr>
                </table>
            </div>
            <div class="footer">
                <p>Printed on: ${formatDate(new Date())}</p>
            </div>
        </body>
        </html>
    `;
    
    // Write to the new window
    printWindow.document.open();
    printWindow.document.write(printContent);
    printWindow.document.close();
};

  
const deleteItemUsage = (id) => {
    if (window.Swal) {
        window.Swal.fire({
            title: 'Delete Spare Usage Record',
            text: 'Are you sure you want to delete this spare usage record?',
            icon: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#3085d6',
            cancelButtonColor: '#d33',
            confirmButtonText: 'Delete'
        }).then(async (result) => {
            if (result.isConfirmed) {
                try {
                    loading_spinner.value = true;
                    await axiosInstance.delete(`/item-usage/${id}`);
                    showMessage(' deleted successfully!');
                    await getCostNote();
                } catch (error) {
                    showError(error.message || 'Delete failed');
                    console.error('Delete error:', error);
                } finally {
                    loading_spinner.value = false;
                }
            }
        });
    }
};



const showRemarkModal = ref(false);
const jobcard_id = ref(0); // Default to 0



 const newremark = ref('');
    const isLoading = ref(false);

const saveRemark = async () => {
    if (!newremark.value.trim()) {
        showError("Remark cannot be empty!");
        return;
    }
    
    // Prepend jobcard info to the remark
    newremark.value = "In jobcard No. " + jobcard_id.value + " for machine type " +  jobcard.value?.machine.type_name + " - " + jobcard.value?.machine.name + " " + newremark.value;
    
    isSending.value = true;
    
    try {
        const remarkData = {
            remarker_id: user_id,
            description: newremark.value,
            status: status.value,
            type_id: jobcard_id.value,
            remark_type: "jobcard",
            remarker: JSON.parse(localStorage.getItem("user")).name
        };
        
        const response = await axiosInstance.post('remark', remarkData);
        
        if (response.status === 201 || response.status === 200) {
            if (response.data) {
                remarks.value.push(response.data);
            } else {
                remarks.value.push(remarkData);
            }
            
            newremark.value = '';
            showMessage("Remark added successfully");
            closeRemarkModal();
        }
    } catch (error) {
        console.log(error);
        showError(error.message);
    } finally {
        isSending.value = false;
    }
};


